getActiveChangesByRisk: function(riskLevel) {
    var results = [];
    var gr = new GlideRecord('change_request');
    gr.addEncodedQuery('active=ture^risk=' + riskLevel);
    gr.query();

    while (gr.next()) {
        results.push(gr.getValue('number'));
    }
    return results;
